200:   public static ObjectMapper newDefaultObjectMapper() {
201:     ObjectMapper objectMapper = new ObjectMapper();
202:     objectMapper.disable(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES);
203:     objectMapper.registerModule(new Jdk8Module());
204:     objectMapper.registerModule(new GuavaModule());
205:     objectMapper.registerModule(new JavaTimeModule());
206:     JsonFactory factory = objectMapper.getFactory();
207:     factory.enable(JsonParser.Feature.ALLOW_UNQUOTED_FIELD_NAMES);
208:     factory.enable(JsonParser.Feature.ALLOW_SINGLE_QUOTES);
209:     return objectMapper;
210:   }
